import React, { useState } from 'react';
import { StyleSheet, Text, View, TextInput, TouchableOpacity, ScrollView, ActivityIndicator } from 'react-native';
import { api } from '../api';

interface RegisterScreenProps {
  token: string | null;
  onRegistrationSuccess: () => void;
}

const formatDob = (text: string) => {
  const cleaned = text.replace(/\D/g, '').slice(0, 8);
  let formatted = '';
  if (cleaned.length > 0) {
    formatted += cleaned.slice(0, 4);
  }
  if (cleaned.length > 4) {
    formatted += '-' + cleaned.slice(4, 6);
  }
  if (cleaned.length > 6) {
    formatted += '-' + cleaned.slice(6, 8);
  }
  return formatted;
};

export const RegisterScreen: React.FC<RegisterScreenProps> = ({ token, onRegistrationSuccess }) => {
  const [fullName, setFullName] = useState('');
  const [gender, setGender] = useState('Male');
  const [dateOfBirth, setDateOfBirth] = useState('');
  const [email, setEmail] = useState('');
  const [bloodGroup, setBloodGroup] = useState('');
  const [profession, setProfession] = useState('');
  const [town, setTown] = useState('');

  // Patient categories states
  const [isExisting, setIsExisting] = useState(false);
  const [hasPatientId, setHasPatientId] = useState(false);
  const [existingPatientId, setExistingPatientId] = useState('');

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleRegister = async () => {
    setError('');

    if (!fullName.trim() || !dateOfBirth.trim() || !profession.trim() || !town.trim()) {
      setError('Please fill in all mandatory fields (*)');
      return;
    }

    // DOB Validation YYYY-MM-DD
    const dobPattern = /^\d{4}-\d{2}-\d{2}$/;
    if (!dobPattern.test(dateOfBirth.trim())) {
      setError('Date of birth must follow YYYY-MM-DD format (e.g. 1985-12-30).');
      return;
    }

    // Optional Email Validation
    if (email.trim()) {
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailPattern.test(email.trim())) {
        setError('Please enter a valid email address.');
        return;
      }
    }

    if (isExisting && hasPatientId && !existingPatientId.trim()) {
      setError('Please enter your existing Patient ID.');
      return;
    }

    setLoading(true);
    setError('');

    try {
      await api.post('/patients/register', {
        fullName: fullName.trim(),
        gender,
        dateOfBirth: dateOfBirth.trim(),
        email: email.trim() || undefined,
        bloodGroup: bloodGroup.trim() || undefined,
        profession: profession.trim(),
        town: town.trim(),
        isExisting,
        existingPatientId: (isExisting && hasPatientId) ? existingPatientId.trim() : null,
      }, token);

      onRegistrationSuccess();
    } catch (err: any) {
      setError(err.message || 'Failed to submit registration. Try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <ScrollView style={styles.scroll} contentContainerStyle={styles.container}>
      <View style={styles.card}>
        <Text style={styles.title}>Register Profile</Text>
        <Text style={styles.subtitle}>AMAR HOSPITAL REGISTRY</Text>

        {error ? <Text style={styles.errorText}>{error}</Text> : null}

        {/* Full Name */}
        <View style={styles.formGroup}>
          <Text style={styles.label}>FULL NAME *</Text>
          <TextInput
            style={styles.input}
            placeholder="John Doe"
            placeholderTextColor="#a0aec0"
            value={fullName}
            onChangeText={setFullName}
          />
        </View>

        {/* Gender Toggle */}
        <View style={styles.formGroup}>
          <Text style={styles.label}>GENDER *</Text>
          <View style={styles.toggleRow}>
            {['Male', 'Female', 'Other'].map((g) => (
              <TouchableOpacity
                key={g}
                style={[styles.toggleBtn, gender === g ? styles.toggleBtnActive : null]}
                onPress={() => setGender(g)}
              >
                <Text style={[styles.toggleText, gender === g ? styles.toggleTextActive : null]}>
                  {g}
                </Text>
              </TouchableOpacity>
            ))}
          </View>
        </View>

        {/* Date of Birth */}
        <View style={styles.formGroup}>
          <Text style={styles.label}>DATE OF BIRTH * (YYYY-MM-DD)</Text>
          <TextInput
            style={styles.input}
            placeholder="1980-05-25"
            placeholderTextColor="#a0aec0"
            value={dateOfBirth}
            onChangeText={(text) => setDateOfBirth(formatDob(text))}
          />
        </View>

        {/* Town */}
        <View style={styles.formGroup}>
          <Text style={styles.label}>TOWN / RESIDENCE AREA *</Text>
          <TextInput
            style={styles.input}
            placeholder="Kochi / Palakkad"
            placeholderTextColor="#a0aec0"
            value={town}
            onChangeText={setTown}
          />
        </View>

        {/* Profession */}
        <View style={styles.formGroup}>
          <Text style={styles.label}>PROFESSION *</Text>
          <TextInput
            style={styles.input}
            placeholder="Farmer / Engineer / Teacher"
            placeholderTextColor="#a0aec0"
            value={profession}
            onChangeText={setProfession}
          />
        </View>

        {/* Email */}
        <View style={styles.formGroup}>
          <Text style={styles.label}>EMAIL (OPTIONAL)</Text>
          <TextInput
            style={styles.input}
            placeholder="john@example.com"
            placeholderTextColor="#a0aec0"
            keyboardType="email-address"
            value={email}
            onChangeText={setEmail}
          />
        </View>

        {/* Blood Group */}
        <View style={styles.formGroup}>
          <Text style={styles.label}>BLOOD GROUP (OPTIONAL)</Text>
          <TextInput
            style={styles.input}
            placeholder="O+ / A- / B+"
            placeholderTextColor="#a0aec0"
            value={bloodGroup}
            onChangeText={setBloodGroup}
          />
        </View>

        {/* PATIENT CLASSIFICATION */}
        <View style={styles.divider} />

        <View style={styles.formGroup}>
          <Text style={styles.label}>Are you an Existing Patient of Amar Hospital?</Text>
          <View style={styles.toggleRow}>
            <TouchableOpacity
              style={[styles.toggleBtn, isExisting ? styles.toggleBtnActive : null]}
              onPress={() => setIsExisting(true)}
            >
              <Text style={[styles.toggleText, isExisting ? styles.toggleTextActive : null]}>Yes</Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={[styles.toggleBtn, !isExisting ? styles.toggleBtnActive : null]}
              onPress={() => { setIsExisting(false); setHasPatientId(false); }}
            >
              <Text style={[styles.toggleText, !isExisting ? styles.toggleTextActive : null]}>No, I am New</Text>
            </TouchableOpacity>
          </View>
        </View>

        {isExisting ? (
          <View style={styles.existingBox}>
            <Text style={styles.label}>Do you already have a Patient ID (e.g. AH000021)?</Text>
            <View style={styles.toggleRow}>
              <TouchableOpacity
                style={[styles.toggleBtn, hasPatientId ? styles.toggleBtnActive : null]}
                onPress={() => setHasPatientId(true)}
              >
                <Text style={[styles.toggleText, hasPatientId ? styles.toggleTextActive : null]}>Yes</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={[styles.toggleBtn, !hasPatientId ? styles.toggleBtnActive : null]}
                onPress={() => { setHasPatientId(false); setExistingPatientId(''); }}
              >
                <Text style={[styles.toggleText, !hasPatientId ? styles.toggleTextActive : null]}>No</Text>
              </TouchableOpacity>
            </View>

            {hasPatientId ? (
              <View style={{ marginTop: 12 }}>
                <Text style={styles.label}>ENTER PATIENT ID *</Text>
                <TextInput
                  style={styles.input}
                  placeholder="AH000001"
                  placeholderTextColor="#a0aec0"
                  autoCapitalize="characters"
                  value={existingPatientId}
                  onChangeText={setExistingPatientId}
                />
              </View>
            ) : null}
          </View>
        ) : null}

        <TouchableOpacity
          style={styles.button}
          onPress={handleRegister}
          disabled={loading}
        >
          {loading ? (
            <ActivityIndicator color="#ffffff" />
          ) : (
            <Text style={styles.buttonText}>Submit Registration</Text>
          )}
        </TouchableOpacity>
      </View>
    </ScrollView>
  );
};

const styles = StyleSheet.create({
  scroll: {
    flex: 1,
    backgroundColor: '#f7f6f2',
  },
  container: {
    padding: 16,
    alignItems: 'center',
    justifyContent: 'center',
    paddingVertical: 24,
  },
  card: {
    backgroundColor: '#ffffff',
    borderWidth: 1,
    borderColor: '#e5e7eb',
    borderRadius: 24,
    padding: 24,
    width: '100%',
    maxWidth: 450,
    shadowColor: '#213932',
    shadowOffset: { width: 0, height: 8 },
    shadowOpacity: 0.04,
    shadowRadius: 16,
    elevation: 2,
  },
  title: {
    fontSize: 24,
    fontWeight: '800',
    color: '#213932',
    textAlign: 'center',
  },
  subtitle: {
    fontSize: 10,
    fontWeight: '700',
    color: '#213932',
    letterSpacing: 2,
    marginTop: 4,
    marginBottom: 24,
    textAlign: 'center',
    opacity: 0.6,
  },
  formGroup: {
    width: '100%',
    marginBottom: 16,
  },
  label: {
    color: '#4a5568',
    fontSize: 11,
    fontWeight: '700',
    letterSpacing: 1,
    marginBottom: 8,
  },
  input: {
    backgroundColor: '#fcfbfa',
    borderWidth: 1,
    borderColor: '#e5e7eb',
    borderRadius: 12,
    paddingHorizontal: 16,
    paddingVertical: 10,
    color: '#1a202c',
    fontSize: 15,
  },
  toggleRow: {
    flexDirection: 'row',
    gap: 8,
  },
  toggleBtn: {
    flex: 1,
    paddingVertical: 10,
    borderRadius: 12,
    borderWidth: 1,
    borderColor: '#e5e7eb',
    backgroundColor: '#fcfbfa',
    alignItems: 'center',
  },
